"""Analyze only the synthetic SDR chart generated by the opt-in Rust color test.
Requires ffmpeg/ffprobe on PATH. Does not read a display, browser, or personal media.
Usage: python scripts/analyze-color-fidelity.py scratch/color-fidelity/fixed --assert-sdr
"""
import json,math,statistics,subprocess,sys
from pathlib import Path
folder=Path(sys.argv[1]); ref=json.loads((folder/'reference.json').read_text(encoding='utf-8'));w=ref['width'];h=ref['height']
def run(args):
 p=subprocess.run(args,capture_output=True)
 if p.returncode:raise RuntimeError(p.stderr.decode('utf-8',errors='replace'))
 return p.stdout
probe=json.loads(run(['ffprobe','-v','error','-count_frames','-show_streams','-of','json',str(folder/'encoded.h264')]))
(folder/'ffprobe.json').write_text(json.dumps(probe,indent=2),encoding='utf-8')
frame_count=int(probe['streams'][0].get('nb_read_frames') or 0)
if frame_count<31:raise RuntimeError('Insufficient decodable frames: need at least 31 to compare frame 30; got '+str(frame_count))
inputs={'source':(folder/'source.bgra').read_bytes()}
if len(inputs['source'])!=w*h*4 or (folder/'conversion.nv12').stat().st_size!=w*h*3//2:raise RuntimeError('Synthetic source/NV12 size mismatch')
for matrix in ['bt601','bt709']:
 for rng in ['tv','pc']:
  out=folder/('conversion_'+matrix+'_'+rng+'.bgra')
  run(['ffmpeg','-v','error','-y','-f','rawvideo','-pixel_format','nv12','-video_size',str(w)+'x'+str(h),'-i',str(folder/'conversion.nv12'),'-vf','scale=in_color_matrix='+matrix+':in_range='+rng+':out_range=pc','-frames:v','1','-pix_fmt','bgra','-f','rawvideo',str(out)])
  inputs['conversion_'+matrix+'_'+rng]=out.read_bytes()
for kind,filters in [('auto',[]),('601_tv',['-vf','select=eq(n\\,30),scale=in_color_matrix=bt601:in_range=tv:out_range=pc']),('709_tv',['-vf','select=eq(n\\,30),scale=in_color_matrix=bt709:in_range=tv:out_range=pc'])]:
 out=folder/('decoded_'+kind+'.bgra')
 args=['ffmpeg','-v','error','-y','-i',str(folder/'encoded.h264')]
 if kind=='auto':args+=['-vf','select=eq(n\\,30)']
 else:args+=filters
 run(args+['-frames:v','1','-pix_fmt','bgra','-f','rawvideo',str(out)])
 inputs['decoded_'+kind]=out.read_bytes()
 if len(inputs['decoded_'+kind])!=w*h*4:raise RuntimeError('Decoder did not produce the requested synthetic frame')
def meanrgb(data,p):
 channels=[[],[],[]]
 for yy in range(p['y'],p['y']+p['height']):
  for xx in range(p['x'],p['x']+p['width']):
   i=(yy*w+xx)*4
   for k in range(3):channels[k].append(data[i+2-k])
 return [round(statistics.mean(c),3) for c in channels]
nv12=(folder/'conversion.nv12').read_bytes();patches=[]
for p in ref['patches']:
 x=p['x']+p['width']//2;y=p['y']+p['height']//2;off=w*h+(y//2)*w+(x//2)*2
 row={'index':p['index'],'rgb':p['rgb'],'yuv':[nv12[y*w+x],nv12[off],nv12[off+1]],'stages':{k:meanrgb(v,p) for k,v in inputs.items()}}
 patches.append(row)
# Compare encoder output samples to the GPU NV12, without a second RGB interpretation.
encoded_nv12=folder/'decoded.nv12'
run(['ffmpeg','-v','error','-y','-i',str(folder/'encoded.h264'),'-vf','select=eq(n\\,30)',
     '-frames:v','1','-pix_fmt','nv12','-f','rawvideo',str(encoded_nv12)])
encoded_bytes=encoded_nv12.read_bytes()
compression_diffs=[]
compression_chroma=[]
for p in ref['patches']:
 for yy in range(p['y'],p['y']+p['height']):
  for xx in range(p['x'],p['x']+p['width']):
   compression_diffs.append(abs(nv12[yy*w+xx]-encoded_bytes[yy*w+xx]))
 for yy in range(p['y']//2,(p['y']+p['height'])//2):
  for xx in range(p['x'],p['x']+p['width']):
   off=w*h+yy*w+xx;compression_chroma.append(abs(nv12[off]-encoded_bytes[off]))
scores={}
for k in inputs:
 if k=='source':continue
 diffs=[abs(row['stages'][k][c]-row['rgb'][c]) for row in patches for c in range(3)]
 scores[k]={'patchMeanAbsoluteRgbError':round(statistics.mean(diffs),3),'patchMaxMeanChannelError':round(max(diffs),3)}
gradient_scores={}
for key,data in inputs.items():
 if key=='source':continue
 regions={}
 for band,name in enumerate(['gray','red','green','blue']):
  diffs=[]
  for y in range(488+band*60,532+band*60):
   for x in range(8,w-8):
    off=(y*w+x)*4
    diffs.extend(abs(data[off+c]-inputs['source'][off+c]) for c in range(3))
  regions[name]={'meanAbsoluteRgbError':round(statistics.mean(diffs),3),'maxChannelError':max(diffs)}
 gradient_scores[key]=regions
result={'decodedFrameCount':frame_count,'comparedFrameIndex':30,'compressionPatchChromaMae':round(statistics.mean(compression_chroma),3),'compressionPatchLumaMae':round(statistics.mean(compression_diffs),3),'gradientScores':gradient_scores,'encoder':ref['encoder'],'gpuStreamColorBits':ref['gpuStreamColorBits'],'gpuOutputColorBits':ref['gpuOutputColorBits'],'mfInput':ref['mfInput'],'mfOutput':ref['mfOutput'],'h264Color':{k:probe['streams'][0].get(k) for k in ['color_range','color_space','color_transfer','color_primaries']},'scores':scores,'patches':patches}
(folder/'measurements.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in result.items() if k!='patches'},indent=2))
print('PATCHES 0-15')
for p in patches[:16]:print(p['index'],p['rgb'],'NV12',p['yuv'],'decoded',p['stages']['decoded_auto'])

if '--assert-sdr' in sys.argv[2:]:
 assert result['h264Color']=={'color_range':'tv','color_space':'bt709','color_transfer':'bt709','color_primaries':'bt709'}, result['h264Color']
 assert result['mfInput']['matrix']==1 and result['mfInput']['range']==2
 assert result['mfOutput']['matrix']==1 and result['mfOutput']['range']==2
 assert result['gpuOutputColorBits']==20 and result['gpuStreamColorBits']==36
 assert scores['conversion_bt709_tv']['patchMeanAbsoluteRgbError']<=2
 assert scores['decoded_auto']['patchMeanAbsoluteRgbError']<=3
 assert scores['decoded_auto']['patchMaxMeanChannelError']<=5
 assert scores['conversion_bt709_tv']['patchMeanAbsoluteRgbError'] < scores['conversion_bt709_pc']['patchMeanAbsoluteRgbError']
 assert result['compressionPatchLumaMae']<=3
 print('PASS: SDR limited BT.709 samples, MF metadata, actual H.264 VUI and RGB thresholds.')
